import React from "react";
import { motion } from "framer-motion";
import { COLLECTIONS } from "../types";
import { ArrowRight } from "lucide-react";

export default function Collections() {
  return (
    <section id="collections" className="py-24 lg:py-32 bg-white">
      <div className="container mx-auto px-6">
        {/* Header */}
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <motion.div className="flex items-center justify-center gap-4 mb-6">
            <div className="h-px w-12 bg-gradient-to-r from-transparent to-amber-400" />
            <span className="text-sm font-semibold tracking-[0.15em] uppercase text-amber-500">Our Products</span>
            <div className="h-px w-12 bg-gradient-to-l from-transparent to-amber-400" />
          </motion.div>
          <h2 className="text-4xl md:text-5xl font-bold text-gray-900" style={{ fontFamily: "Georgia, serif" }}>
            Shop by <span className="text-amber-500">Category</span>
          </h2>
        </motion.div>

        {/* Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {COLLECTIONS.map((collection, i) => (
            <motion.div
              key={collection.id}
              className="group relative overflow-hidden rounded-3xl aspect-[4/5] cursor-pointer"
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.1, duration: 0.6 }}
              whileHover={{ y: -10 }}
            >
              {/* Image */}
              <img
                src={collection.image}
                alt={collection.title}
                className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
              />

              {/* Gradient Overlay */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent" />

              {/* Glow Effect on Hover */}
              <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500 bg-gradient-to-t from-amber-500/20 to-transparent" />

              {/* Content */}
              <div className="absolute inset-0 flex flex-col justify-end p-6">
                <motion.span
                  className="text-xs font-semibold text-amber-400 uppercase tracking-wider mb-2"
                  initial={{ opacity: 0, y: 20 }}
                  whileHover={{ opacity: 1, y: 0 }}
                >
                  {collection.overline}
                </motion.span>
                <h3 className="text-xl font-bold text-white mb-2" style={{ fontFamily: "Georgia, serif" }}>
                  {collection.title}
                </h3>
                <p className="text-sm text-white/70 mb-4 line-clamp-2 opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300">
                  {collection.desc}
                </p>
                <div className="flex items-center gap-2 text-amber-400 text-sm font-medium opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-500">
                  <span>View Details</span>
                  <ArrowRight size={16} className="group-hover:translate-x-1 transition-transform" />
                </div>
              </div>

              {/* Border Glow */}
              <div className="absolute inset-0 rounded-3xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 border-2 border-amber-400/50" />
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
